        ("03.2", "user-menu-signout", "User menu, keyboard on Sign out", "every page", "The focus ring inside the menu item; ↑ and ↓ move, Enter chooses, Esc closes and returns the focus to your name."),
        ("04", "toast-success", "Toast, success", "any page", "A confirmation that names what happened; it leaves by itself and can be dismissed."),
